using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering;using Newtonsoft.Json;
public static class F1SunsetApply {
 const string E="Assets/Afrer_Seconds/05.Model/Environment/1F/";static string Root=>Path.GetFullPath(Application.dataPath+"/../../..");
 public static object Run(){var scene=SceneManager.GetActiveScene();if(scene.isDirty||Application.isPlaying||!scene.path.EndsWith("Level_1F_Factory.unity"))throw new Exception("Saved 1F required");
 File.Copy(Root+"/SourceAssets/F1_SunsetSky/FS_SunsetSky.shader",E+"FS_SunsetSky.shader",true);AssetDatabase.ImportAsset(E+"FS_SunsetSky.shader",ImportAssetOptions.ForceSynchronousImport|ImportAssetOptions.ForceUpdate);var shader=AssetDatabase.LoadAssetAtPath<Shader>(E+"FS_SunsetSky.shader");if(ShaderUtil.ShaderHasError(shader))throw new Exception("Sky shader compilation failed");string path=E+"Materials/FS_SunsetSky.mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(shader){name="FS_SunsetSky"};AssetDatabase.CreateAsset(m,path);}m.shader=shader;
 var sun=RenderSettings.sun;if(!sun||sun.type!=LightType.Directional)throw new Exception("Existing sun not found");sun.transform.rotation=Quaternion.Euler(5,88,0);sun.color=new Color(1,.60f,.32f);sun.intensity=1.12f;sun.useColorTemperature=false;
 m.SetVector("_SunDirection",-sun.transform.forward);m.SetColor("_Zenith",new Color(.045f,.050f,.135f));m.SetColor("_Horizon",new Color(.90f,.30f,.11f));m.SetColor("_Opposite",new Color(.34f,.18f,.24f));m.SetColor("_SunColor",new Color(4,2.25f,.8f));m.SetFloat("_SunRadius",.009f);m.SetFloat("_CloudAmount",.48f);m.SetFloat("_Exposure",1);
 RenderSettings.skybox=m;RenderSettings.ambientMode=AmbientMode.Trilight;RenderSettings.ambientSkyColor=new Color(.40f,.38f,.49f);RenderSettings.ambientEquatorColor=new Color(.46f,.34f,.29f);RenderSettings.ambientGroundColor=new Color(.23f,.18f,.19f);RenderSettings.ambientIntensity=1;
 RenderSettings.fog=true;RenderSettings.fogMode=FogMode.Linear;RenderSettings.fogColor=new Color(.63f,.38f,.30f);RenderSettings.fogStartDistance=280;RenderSettings.fogEndDistance=3100;
 foreach(var sky in scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Skybox>(true)))sky.material=m;
 // Existing room bounce lights remain in place, with a dusk tint rather than daylight blue.
 var bounce=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Light>(true)).Where(l=>l.name.EndsWith("_DiffuseSkyBounce")).ToArray();foreach(var l in bounce){l.color=new Color(.62f,.53f,.60f);l.intensity=l.name.StartsWith("C")?.46f:.38f;}
 EditorUtility.SetDirty(m);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);SceneView.RepaintAll();var result=new{scene=scene.path,sky=path,sun=sun.name,rotation=new[]{5,88,0},sun.intensity,roomBounceLights=bounce.Length,saved=true};File.WriteAllText(Root+"/Docs/Review/2026-11-13_1F_SunsetSky/apply.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
